from pathlib import Path
r=Path(__file__).resolve().parents[1];g=r/'game.js';s=g.read_text()
s=s.replace("x:640,y:FLOOR,vy:0,onGround:true,guard:false,dashCooldown:0,", "x:640,y:FLOOR,vy:0,onGround:true,guard:false,haste:0,dashCooldown:0,")
s=s.replace("onGround:true,guard:false,dashCooldown:0,attackPose:0,animation:'idle1'", "onGround:true,guard:false,haste:0,dashCooldown:0,attackPose:0,animation:'idle1'")
s=s.replace("slow:0,hitFreeze:0,guardMeter:100,guardBreak:0", "slow:0,haste:0,hitFreeze:0,guardMeter:100,guardBreak:0")
s=s.replace("p.slow=Math.max(0,p.slow-dt);", "p.slow=Math.max(0,p.slow-dt);p.haste=Math.max(0,(p.haste||0)-dt);")
s=s.replace("HEROES[p.hero].speed*1.40*(p.slow>0?.64:1)","HEROES[p.hero].speed*1.40*(p.haste>0?1.19:1)*(p.slow>0?.64:1)")
s=s.replace("const item={id:'h'+(this.nextPickupId++),type:'heal',x:pos.x,y:pos.y,ttl:17,amount:30};", "const type=['heal','mana','haste'][(this.spawnCounter-1)%3];const item={id:'h'+(this.nextPickupId++),type,x:pos.x,y:pos.y,ttl:17,amount:type==='heal'?30:type==='mana'?38:7};")
s=s.replace("this.broadcast({type:'pickupSpawn',id:item.id,x:item.x,y:item.y});", "this.broadcast({type:'pickupSpawn',id:item.id,x:item.x,y:item.y,kind:item.type});")
s=s.replace("const nearby=this.players.filter(p=>p.alive&&p.hp<HEROES[p.hero].hp-1)\n        .find(p=>Math.abs(p.x-item.x)<50&&Math.abs((p.y-70)-item.y)<76);\n      if(nearby){const recovered=Math.min(item.amount,HEROES[nearby.hero].hp-nearby.hp);\n        nearby.hp+=recovered;this.broadcast({type:'pickup',by:nearby.id,amount:Math.round(recovered),x:item.x,y:item.y});\n        this.effects.push({kind:'heal',x:item.x,y:item.y,r:80,ttl:.85,color:'#a6ffbd',by:nearby.id});return false;}","const nearby=this.players.filter(p=>p.alive&&(item.type==='mana'?p.mana<HEROES[p.hero].mana-1:item.type==='haste'?p.haste<1:p.hp<HEROES[p.hero].hp-1))\n        .find(p=>Math.abs(p.x-item.x)<50&&Math.abs((p.y-70)-item.y)<76);\n      if(nearby){let gained=item.amount;\n        if(item.type==='mana'){gained=Math.min(item.amount,HEROES[nearby.hero].mana-nearby.mana);nearby.mana+=gained;}\n        else if(item.type==='haste'){nearby.haste=Math.max(nearby.haste,7);gained=7;}\n        else{gained=Math.min(item.amount,HEROES[nearby.hero].hp-nearby.hp);nearby.hp+=gained;}\n        this.broadcast({type:'pickup',by:nearby.id,kind:item.type,amount:Math.round(gained),x:item.x,y:item.y});\n        this.effects.push({kind:item.type==='mana'?'mana':item.type==='haste'?'dash':'heal',x:item.x,y:item.y,r:80,ttl:.85,color:item.type==='mana'?'#97e4ff':item.type==='haste'?'#ffe48d':'#a6ffbd',by:nearby.id});return false;}")
s=s.replace("slow:p.slow>0,combo:p.combo||0", "slow:p.slow>0,haste:(p.haste||0)>0,combo:p.combo||0")
g.write_text(s)
# V6 client visuals: 3 pickups including mana and haste
c=r/'public/game-client.js';s=c.read_text()
s=s.replace("const x=item.x,y=item.y+Math.sin(t*3+item.x)*7;", "const x=item.x,y=item.y+Math.sin(t*3+item.x)*7;const itemColor=item.type==='mana'?'#7dbfff':item.type==='haste'?'#ffcf72':'#90ffc2';")
s=s.replace("glow.addColorStop(0,'#bdffb7aa');glow.addColorStop(1,'#88ffbd00');", "glow.addColorStop(0,item.type==='mana'?'#87bfffa9':item.type==='haste'?'#ffe18ca9':'#bdffb7aa');glow.addColorStop(1,'#88ffbd00');")
s=s.replace("ctx.fillStyle='#15472c';ctx.fillRect(-19,-23,38,46);ctx.fillStyle='#9efbcc';ctx.fillRect(-14,-18,28,36);", "ctx.fillStyle=item.type==='mana'?'#163f77':item.type==='haste'?'#8b5826':'#15472c';ctx.fillRect(-19,-23,38,46);ctx.fillStyle=itemColor;ctx.fillRect(-14,-18,28,36);")
s=s.replace("stroked('HP +30',x,y-46,'bold 15px sans-serif','#caffba','#18512b',4);", "stroked(item.type==='mana'?'MP +38':item.type==='haste'?'HASTE ×7s':'HP +30',x,y-46,'bold 15px sans-serif',itemColor,'#20243b',4);")
s=s.replace("const a=snap.players.find(v=>v.id!==myId);", "const a=snap.players.find(v=>v.id!==myId);")
s=s.replace("$('guardFill').classList.toggle('warning',p.guardMeter<30);", "$('guardFill').classList.toggle('warning',p.guardMeter<30);if(p.haste){$('myState').textContent += ' · ⚡ 가속 효과';}")
c.write_text(s)
print('pickup patched')
